DROP TABLE IF EXISTS `listing_master`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `listing_master` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `business_name` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `category` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'Uncategorized',
  `city` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL,
  `address` text COLLATE utf8mb4_unicode_ci,
  `phone` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `source` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL,
  `dedupe_hash` char(64) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'sha256(name|city|address|source) - prevents duplicate rows',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_listing_dedupe` (`dedupe_hash`),
  KEY `ix_listing_city` (`city`),
  KEY `ix_listing_category` (`category`),
  KEY `ix_listing_source` (`source`)
) ENGINE=InnoDB AUTO_INCREMENT=2205 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
